mapper.select:
select 
from ry_rental.ry_rental_platform_operations_alert_event

    is_delete = 0
    and alert_type = #{query.alertType}
    and alert_level = #{query.alertLevel}
    and event_status = #{query.eventStatus}

        and (title like concat('%', #{query.keyword}, '%')
          or detail like concat('%', #{query.keyword}, '%')
          or source_key like concat('%', #{query.keyword}, '%'))


order by field(event_status, 0, 1, 2), alert_level desc, last_seen_time desc, alert_event_id desc

mapper.update:
update ry_rental.ry_rental_platform_operations_alert_event set event_status = 2, resolved_by = #{operator}, resolved_time = now(), resolved_remark = '观察窗口内未再次发现调度失败', update_by = #{operator}, update_time = now() where alert_type = 1 and event_status in (0, 1) and is_delete = 0 and last_seen_time < date_sub(now(), interval 24 hour)
and alert_event_key not in
#{alertEventKey}
